    static final int MASK = 16383;

    static StringBuilder searchData = new StringBuilder();
    static double enemyEnergy, direction = 1, won, mode, tab, speed, bv;

    public void run() {
        setAdjustGunForRobotTurn(true);
        setAdjustRadarForGunTurn(true);
        setTurnRadarRightRadians(Double.POSITIVE_INFINITY);
    }

    public void onScannedRobot(ScannedRobotEvent e) {
        double angle, absBearing, distance, drop, offset, antiRam, eOffset;
        distance = e.getDistance();
        speed = (int) (tab = MODES.charAt(e.getName().hashCode() & MASK)) >> 4;
        offset = 2 + (antiRam = (int) (100 / distance));
        do {
            angle = (absBearing = e.getBearingRadians() + getHeadingRadians()) + direction * (offset -= 0.02);
        } while (!FIELD.contains(getX() + 160 * Math.sin(angle), getY() + 160 * Math.cos(angle)));
        setTurnRightRadians(Math.tan(angle -= getHeadingRadians()));
        if ((drop = enemyEnergy - (enemyEnergy = e.getEnergy())) > mode - antiRam) {
            setAhead(Math.copySign((3 + (int) (drop * 1.999999)) << 3, Math.cos(angle)));
        }
        if (Math.random() + antiRam < (0.6 * Math.sqrt(bv / distance) - 0.04) * -mode || offset < 0.9) {
            direction = -direction;
        }

        // Cotillion's gun, verbatim but for the names.
        Rectangle2D.Double field = new Rectangle2D.Double(18 - getX(), 18 - getY(), 764, 564);
        searchData.insert(0, (char) (
            (4 + Math.round((float) (e.getVelocity() * Math.cos(eOffset = e.getHeadingRadians() - absBearing)) / 2f))
            | ((int) Math.round(eOffset = e.getVelocity() * Math.sin(eOffset)) << 11)
            | 0x10 * (int) Math.signum(field.outcode(distance * Math.sin(eOffset = absBearing + 0.75 * Math.signum(eOffset)),
                distance * Math.cos(eOffset)))));
        double bulletPower = antiRam + Math.min(2, enemyEnergy / 4);
        int[] index = new int[50];
        int[] bins = new int[BINS];
        int keyLength = Math.min(searchData.length(), 30);
        int tempIndex = 0;
        search:
        try {
            do {
                do {
                    if (tempIndex < 0) {
                        keyLength--;
                    }
                    if (keyLength <= index[0]) {
                        break search;
                    }
                    tempIndex = searchData.indexOf(searchData.substring(0, keyLength), tempIndex + 2);
                } while (tempIndex * Arrays.binarySearch(index, tempIndex) >= 0);
                int iterateIndex = index[0] = tempIndex;
                Arrays.sort(index);
                double db = eOffset = 0;
                double goAngle = distance;
                rebuild:
                try {
                    do {
                        char comboChar = searchData.charAt(iterateIndex--);
                        eOffset += ((short) comboChar >> 11) / (goAngle += 2 * ((int) (comboChar & 0x0F) - 4));
                        if (!field.contains(goAngle * Math.sin(absBearing + eOffset), goAngle * Math.cos(absBearing + eOffset))) {
                            break rebuild;
                        }
                    } while ((db += Rules.getBulletSpeed(bulletPower)) < goAngle);
                    bins[(int) (Utils.normalAbsoluteAngle(eOffset) * ((BINS - 1) / (2 * Math.PI)))] += keyLength;
                } catch (Exception ex) {
                }
            } while (true);
        } catch (Exception ex) {
        }
        keyLength = 0;
        tempIndex = 0;
        try {
            while (true) {
                if (bins[++keyLength] > bins[tempIndex]) {
                    tempIndex = keyLength;
                }
            }
        } catch (Exception ex) {
        }
        if (getEnergy() > bulletPower) {
            setFire(bulletPower);
        }
        setTurnGunRightRadians(Utils.normalRelativeAngle(absBearing + 0.5 * (2 * Math.PI / (BINS - 1))
            + getVelocity() * Math.sin(e.getBearingRadians()) / distance
            + tempIndex * (2 * Math.PI / (BINS - 1)) - getGunHeadingRadians()));
        setTurnRadarRightRadians(Utils.normalRelativeAngle(absBearing - getRadarHeadingRadians()) * 2);
    }

    public void onBulletHit(BulletHitEvent e) {
        enemyEnergy -= Rules.getBulletDamage(e.getBullet().getPower());
    }

    public void onHitByBullet(HitByBulletEvent e) {
        double gain;
        enemyEnergy += gain = Rules.getBulletHitBonus(e.getPower());
        bv = e.getVelocity();
        if ((won += gain) > (40 + 23 * getRoundNum()) * (tab % 16)) {
            mode = -1;
        }
    }
